void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File directory = new File(dir);
        if (!directory.exists() || !directory.isDirectory()) {
            throw new IllegalArgumentException("Provided path is not a valid directory: " + dir);
        }

        File[] files = directory.listFiles((d, name) -> name.endsWith(".jar"));
        if (files != null) {
            for (File file : files) {
                cpV.add(file.toURI().toURL());
            }
        }
    } catch (MalformedURLException e) {
        throw new RuntimeException("Error adding JAR file to classpath", e);
    }
}

void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File directory = new File(dir);
        if (directory.exists() && directory.isDirectory()) {
            File[] files = directory.listFiles((d, name) -> name.endsWith(".jar"));
            if (files != null) {
                for (File file : files) {
                    URL url = file.toURI().toURL();
                    cpV.add(url);
                }
            }
        } else {
            throw new IllegalArgumentException("The provided directory does not exist or is not a directory: " + dir);
        }
    } catch (MalformedURLException e) {
        e.printStackTrace();
    }
}

