long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the start of the week for the given dayStep
        int startDay = day - (day - 1) % dayStep;

        // Handle the case where the startDay goes back to the previous month
        if (startDay <= 0) {
            if (month == 1) {
                year--;
                month = 12;
                startDay = 31 + startDay;
            } else {
                month--;
                // Simplified daysInPreviousMonth calculation
                int daysInPreviousMonth = 31; // Approximation, does not account for February, April, June, Sept, Nov
                if (month == 4 || month == 6 || month == 9 || month == 11) {
                    daysInPreviousMonth = 30;
                } else if (month == 2) {
                    // Approximation, does not account for leap years
                    daysInPreviousMonth = 28;
                }
                startDay = daysInPreviousMonth + startDay;
            }
        }

        return year * 10000 + month * 100 + startDay;
    } catch (Exception e) {
        // Log the exception or handle it as needed
        return timeBucket; // Return the original timeBucket in case of error
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
