        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the adjusted day based on dayStep
        int adjustedDay = day - (day % dayStep) + 1;

        // Handle the case where the adjusted day is 0
        if (adjustedDay == 0 && day > 0) {
            adjustedDay = dayStep;
        }

        return year * 10000 + month * 100 + adjustedDay;
    } catch (Exception e) {
