int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index or length is out of bounds");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char nextChar = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextChar)) {
                    size += 4; // surrogate pair
                    i++; // skip the low surrogate
                } else {
                    size += 3; // high surrogate with no pair
                }
            } else {
                size += 3; // high surrogate at the end
            }
        } else {
            size += 3;
        }
    }
    return size;
}

