        int len = str.length();
        int i = 0;
        while (i < len) {
            char c = str.charAt(i++);
            if (c >= 0 && c <= 0x7F) {
                lb = lb.ensureCapacity(1, session);
                lb.buffer[lb.pos++] = (byte) c;
            } else if (c <= 0x7FF) {
                lb = lb.ensureCapacity(2, session);
                lb.buffer[lb.pos++] = (byte) (0xC0 | (c >> 6));
                lb.buffer[lb.pos++] = (byte) (0x80 | (c & 0x3F));
            } else {
                int codePoint = c;
                if (Character.isHighSurrogate(c) && i < len) {
                    char low = str.charAt(i++);
                    if (Character.isLowSurrogate(low)) {
                        codePoint = Character.toCodePoint(c, low);
                    } else {
                        throw new IllegalArgumentException("Invalid surrogate pair");
                    }
                }
                if (codePoint <= 0xFFFF) {
                    lb = lb.ensureCapacity(3, session);
                    lb.buffer[lb.pos++] = (byte) (0xE0 | ((codePoint >> 12) & 0x0F));
                    lb.buffer[lb.pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    lb.buffer[lb.pos++] = (byte) (0x80 | (codePoint & 0x3F));
                } else {
                    lb = lb.ensureCapacity(4, session);
                    lb.buffer[lb.pos++] = (byte) (0xF0 | ((codePoint >> 18) & 0x07));
                    lb.buffer[lb.pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    lb.buffer[lb.pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    lb.buffer[lb.pos++] = (byte) (0x80 | (codePoint & 0x3F));
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to write UTF-8 string", e);
    }
    return lb;
}

