List<PathSegmentImpl> function ( URI u , boolean decode ) { 
    List<PathSegmentImpl> pathSegments = new ArrayList<>(); 
    if ( u == null ) { 
        return pathSegments; 
    } 
    try { 
        String path = u.getPath(); 
        if ( path == null || path.isEmpty() ) { 
            return pathSegments; 
        } 
        if ( path.startsWith("/") ) { 
            path = path.substring(1); 
        } 
        String[] segments = path.split("/"); 
        for ( String segment : segments ) { 
            if ( decode ) { 
                segment = URLDecoder.decode(segment, "UTF-8"); 
            } 
            pathSegments.add(new PathSegmentImpl(segment, false)); 
        } 
    } catch ( Exception e ) { 
        throw new RuntimeException(e); 
    } 
    return pathSegments; 
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    boolean isAbsolute = path.startsWith("/");
    String[] segments = path.split("/");
    int startIndex = isAbsolute ? 1 : 0; // Skip leading '/' if path is absolute
    for (int i = startIndex; i < segments.length; i++) {
        String segment = segments[i];
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("UTF-8 encoding not supported", e);
            }
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    boolean isAbsolute = path.startsWith("/");
    StringTokenizer tokenizer = new StringTokenizer(path, "/", true);
    StringBuilder segmentBuilder = new StringBuilder();
    while (tokenizer.hasMoreTokens()) {
        String token = tokenizer.nextToken();
        if (token.equals("/")) {
            if (isAbsolute && segmentBuilder.length() == 0) {
                continue; // Skip the leading '/' for absolute paths
            }
            if (segmentBuilder.length() > 0) {
                String segment = segmentBuilder.toString();
                pathSegments.add(new PathSegmentImpl(decode ? decode(segment) : segment, Collections.emptyList()));
                segmentBuilder.setLength(0);
            }
        } else {
            segmentBuilder.append(token);
        }
    }
    if (segmentBuilder.length() > 0) {
        String segment = segmentBuilder.toString();
        pathSegments.add(new PathSegmentImpl(decode ? decode(segment) : segment, Collections.emptyList()));
    }
    return pathSegments;
}

private static String decode(String segment) {
    try {
        return URLDecoder.decode(segment, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
}

