private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.startsWith("(")) { // Method descriptor
        int index = descriptor.indexOf(')');
        if (index == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argsDescriptor = descriptor.substring(1, index);
        while (!argsDescriptor.isEmpty()) {
            char typeChar = argsDescriptor.charAt(0);
            switch (typeChar) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'S':
                case 'J':
                case 'Z':
                    argsDescriptor = argsDescriptor.substring(1);
                    break;
                case 'L':
                    index = argsDescriptor.indexOf(';');
                    if (index == -1) {
                        throw new IllegalArgumentException("Invalid object descriptor: missing ';'");
                    }
                    argsDescriptor = argsDescriptor.substring(index + 1);
                    break;
                case '[':
                    int brackets = 1;
                    while (brackets > 0 && index < argsDescriptor.length()) {
                        index++;
                        if (argsDescriptor.charAt(index - 1) == '[') {
                            brackets++;
                        } else if (argsDescriptor.charAt(index - 1) == ']') {
                            brackets--;
                        }
                    }
                    if (brackets != 0) {
                        throw new IllegalArgumentException("Invalid array descriptor");
                    }
                    argsDescriptor = argsDescriptor.substring(index);
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor: " + typeChar);
            }
        }
    } else { // Field descriptor
        char typeChar = descriptor.charAt(0);
        switch (typeChar) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'S':
            case 'J':
            case 'Z':
                break;
            case 'L':
                if (descriptor.indexOf(';') != descriptor.length() - 1) {
                    throw new IllegalArgumentException("Invalid object descriptor: missing ';'");
                }
                break;
            case '[':
                if (descriptor.charAt(descriptor.length() - 1) != ';') {
                    int brackets = 1;
                    for (int i = 1; i < descriptor.length(); i++) {
                        if (descriptor.charAt(i) == '[') {
                            brackets++;
                        } else if (descriptor.charAt(i) == ']') {
                            brackets--;
                            if (brackets == 0) {
                                typeChar = descriptor.charAt(i + 1);
                                if (!Character.isLowerCase(typeChar) && typeChar != 'L') {
                                    throw new IllegalArgumentException("Invalid array descriptor element: " + typeChar);
                                }
                                break;
                            }
                        }
                    }
                    if (brackets != 0 || typeChar != 'L' || descriptor.lastIndexOf(';') != descriptor.length() - 1) {
                        throw new IllegalArgumentException("Invalid array descriptor");
                    }
                }
                break;
            default:
                throw new IllegalArgumentException("Unknown type descriptor: " + typeChar);
        }
    }
}

