        Box2D leftBox = new Box2D(box.getX(), box.getY(), midX - box.getX(), box.getHeight());
        Box2D rightBox = new Box2D(midX, box.getY(), box.getX() + box.getWidth() - midX, box.getHeight());
        return new Pair<>(leftBox, rightBox);
    } catch (NullPointerException e) {
        throw new IllegalArgumentException("The provided box must not be null", e);
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("The box dimensions must be valid", e);
    }
}

