protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0, Collections.emptyList());
    }

    List<E> edgeList = new ArrayList<>(tour);
    Map<V, E> edgeMap = new HashMap<>();
    V startVertex = null;

    // Build a map to find edges outgoing from each vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        edgeMap.put(source, edge);
        if (startVertex == null) {
            startVertex = source;
        }
    }

    // Construct the path
    List<E> path = new ArrayList<>();
    V currentVertex = startVertex;
    while (true) {
        E currentEdge = edgeMap.get(currentVertex);
        if (currentEdge == null) {
            break; // Cycle completed or graph is incomplete
        }
        path.add(currentEdge);
        currentVertex = graph.getEdgeTarget(currentEdge);
        edgeMap.remove(graph.getEdgeSource(currentEdge)); // Remove to prevent cycles in the path
    }

    // Calculate total weight
    double weight = 0;
    for (E edge : path) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, weight, path);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    List<E> edgesList = new ArrayList<>(tour);
    List<V> vertices = new ArrayList<>();
    V startVertex = graph.getEdgeSource(edgesList.get(0));
    vertices.add(startVertex);

    try {
        V currentVertex = startVertex;
        boolean[] visited = new boolean[edgesList.size()];
        for (int i = 0; i < visited.length; i++) {
            for (int j = 0; j < edgesList.size(); j++) {
                if (!visited[j]) {
                    E edge = edgesList.get(j);
                    V source = graph.getEdgeSource(edge);
                    V target = graph.getEdgeTarget(edge);
                    if (source.equals(currentVertex)) {
                        vertices.add(target);
                        currentVertex = target;
                        visited[j] = true;
                        break;
                    } else if (target.equals(currentVertex)) {
                        vertices.add(source);
                        currentVertex = source;
                        visited[j] = true;
                        break;
                    }
                }
            }
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid tour", e);
    }

    return new SimpleGraphPath<>(graph, vertices);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, new ArrayList<>(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);

    V currentVertex = startVertex;
    Set<E> usedEdges = new HashSet<>();

    while (vertexList.size() <= tour.size()) {
        E nextEdge = null;
        for (E edge : tour) {
            if (!usedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
        }
        usedEdges.add(nextEdge);

        V nextVertex;
        if (graph.getEdgeSource(nextEdge).equals(currentVertex)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }

        vertexList.add(nextVertex);
        currentVertex = nextVertex;

        if (nextVertex.equals(startVertex)) {
            break;
        }
    }

    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> pathEdges = new ArrayList<>(tour);
    if (pathEdges.isEmpty()) {
        return new GraphPathImpl<>(graph, null, pathEdges, 0.0);
    }

    Map<V, E> incomingEdges = new HashMap<>();
    Map<V, E> outgoingEdges = new HashMap<>();

    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        outgoingEdges.put(source, edge);
        incomingEdges.put(target, edge);
    }

    V startVertex = null;
    for (V vertex : graph.vertexSet()) {
        if (!incomingEdges.containsKey(vertex) || !outgoingEdges.containsKey(vertex)) {
            startVertex = vertex;
            break;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("The tour does not form a valid path");
    }

    List<V> pathVertices = new ArrayList<>();
    V currentVertex = startVertex;
    double pathWeight = 0.0;

    while (currentVertex != null) {
        pathVertices.add(currentVertex);
        E currentEdge = outgoingEdges.get(currentVertex);
        if (currentEdge == null) break;
        pathWeight += graph.getEdgeWeight(currentEdge);
        currentVertex = graph.getEdgeTarget(currentEdge);
        outgoingEdges.remove(graph.getEdgeSource(currentEdge));
    }

    return new GraphPathImpl<>(graph, startVertex, pathEdges, pathWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    // Assuming the graph is connected and the tour is a valid path
    V start = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexPath = new ArrayList<>();
    vertexPath.add(start);

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (vertexPath.get(vertexPath.size() - 1).equals(source)) {
            vertexPath.add(target);
        } else if (vertexPath.get(vertexPath.size() - 1).equals(target)) {
            vertexPath.add(source);
        } else {
            throw new IllegalArgumentException("Edges in tour are not connected");
        }
    }

    return new GraphPathImpl<>(graph, start, vertexPath.get(vertexPath.size() - 1), vertexPath, edgeList);
}

