int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int nameIndex = read16(i + 1);
            int descriptorIndex = read16(i + 3);
            String foundName = utf8s[nameIndex];
            String foundDescriptor = utf8s[descriptorIndex];
            if (foundName.equals(name) && foundDescriptor.equals(descriptor)) {
                return i;
            }
        }
    }
    ensureCapacity(maxPoolSize + 2);
    int nameIndex = findUtf8(name);
    int descriptorIndex = findUtf8(descriptor);
    if (nameIndex == NOT_FOUND) {
        nameIndex = addUtf8(name);
    }
    if (descriptorIndex == NOT_FOUND) {
        descriptorIndex = addUtf8(descriptor);
    }
    write16(maxPoolSize, NAME_TYPE);
    write16(maxPoolSize + 1, nameIndex);
    write16(maxPoolSize + 3, descriptorIndex);
    types[maxPoolSize] = NAME_TYPE;
    maxPoolSize += 4;
    offsets[maxPoolSize] = offsets[maxPoolSize - 4] + 4;
    return maxPoolSize - 4;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int nameIndex = readValue(i++);
            int descriptorIndex = readValue(i);
            if (utf8s[nameIndex].equals(name) && utf8s[descriptorIndex].equals(descriptor)) {
                return i - 1; // Return the index of the existing NameAndType
            }
        } else {
            if (types[i] == LONG || types[i] == DOUBLE) {
                i++; // Skip the next entry as well
            }
        }
    }
    // If not found, add a new NameAndType entry
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);
    ensureCapacity(maxPoolSize + 2); // Ensure there's room for two more entries
    types[maxPoolSize++] = NAME_TYPE;
    writeValue(maxPoolSize - 1, nameIndex);
    writeValue(maxPoolSize - 1, descriptorIndex);
    return maxPoolSize - 2; // Return the index of the newly added NameAndType
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int nameIndex = readValue(i);
            int descriptorIndex = readValue(i + 1);
            if (utf8s[nameIndex].equals(name) && utf8s[descriptorIndex].equals(descriptor)) {
                return i;
            }
        }
    }
    if (maxPoolSize + 2 > poolSize) {
        throw new IllegalStateException("Constant pool overflow");
    }
    appendNameAndType(name, descriptor);
    return maxPoolSize - 2;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
