    if (maxPoolSize + 2 > types.length) {
        resizeConstantPool();
    }
    types[maxPoolSize] = NAME_TYPE;
    offsets[maxPoolSize] = (short) maxPoolSize;
    byteCode[maxPoolSize++] = (byte) (nameIndex >> 8);
    byteCode[maxPoolSize++] = (byte) (nameIndex & 0xFF);
    types[maxPoolSize] = NAME_TYPE;
    offsets[maxPoolSize] = (short) maxPoolSize;
    byteCode[maxPoolSize++] = (byte) (descriptorIndex >> 8);
    byteCode[maxPoolSize++] = (byte) (descriptorIndex & 0xFF);
    return maxPoolSize - 2;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            String[] existing = (String[]) readValue(i);
            if (existing[0].equals(name) && existing[1].equals(descriptor)) {
                return i;
            }
        }
    }
    int index = maxPoolSize++;
    types[index] = NAME_TYPE;
    offsets[index] = (byte) 0;
    _putProperty(_types, Integer.toString(index), new String[]{name, descriptor});
    return index;
}

